# Intermediate unit 14 – Out. Bám sách: trang 32–33 (đã xem ảnh trang) + đáp án + Mini dictionary. Không chép nguyên văn.
# leave out, cut out sth (u2), sort out (giải quyết – u1) đã có thẻ; sort out nghĩa ‘sắp xếp cho gọn’ là mới. Trang in đậm tính từ worn-out (Mini ghi động từ wear out) → thẻ worn-out.
theory = (
 H("A", "Out meaning not in", "Out nghĩa là ‘ra ngoài, không ở trong’")
 + T([
   ("leave out sth/sb", "not include something or someone – e.g. skip one exercise (card in Unit 2)", "bỏ ra, không tính vào (đã có thẻ ở bài 2)"),
   ("cut out sth", "remove by cutting paper or cloth – pieces from dress material (card in Unit 2)", "cắt ra từ giấy, vải (đã có thẻ ở bài 2)"),
   ("show out sb", "take a visitor who is leaving to the door", "dẫn khách ra cửa"),
   ("see out sb", "go to the door with someone who is leaving", "tiễn ai ra cửa"),
   ("let out sb/sth", "allow a person or animal to leave, often by opening a locked door", "cho ai/con vật ra ngoài, thường bằng cách mở cửa khóa"),
   ("lock out sb", "stop someone getting into a building by locking the door", "khóa cửa không cho ai vào"),
   ("lock yourself out", "accidentally shut the door with your keys still inside", "lỡ khóa cửa mà để chìa trong nhà/xe"),
 ])
 + H("B", "Out meaning to the end or completely", "Out nghĩa là ‘đến cùng, hoàn toàn’")
 + P("A Sunday at home: someone <b>sorts out</b> their room (arranges untidy things), <b>clears out</b> the wardrobes (removes unwanted things), throws away <b>worn-out</b> shoes (used so much they are damaged – from <i>wear out</i>) and has <b>run out</b> of furniture polish (has none left).",
     "Một ngày Chủ nhật ở nhà: ai đó <b>sorts out</b> căn phòng (sắp xếp đồ bừa bộn), <b>clears out</b> tủ quần áo (dọn bỏ đồ không cần), vứt những đôi giày <b>worn-out</b> (dùng nhiều đến hỏng – từ <i>wear out</i>) và đã <b>run out</b> xi đánh đồ gỗ (hết sạch).")
 + H("C", "Other uses of out", "Các cách dùng khác của out")
 + T([
   ("spread out", "arrange things on a flat surface – photos on a table", "bày ra trên mặt phẳng – ảnh trên bàn"),
   ("come out", "become available to buy – a band’s new album", "được phát hành – album mới của ban nhạc"),
   ("try out", "test something to see if it works or if you like it – a bike", "dùng thử – chiếc xe đạp"),
   ("help out", "help, especially by doing work or giving money – in a busy office", "giúp một tay, nhất là làm việc hoặc cho tiền – ở văn phòng bận rộn"),
   ("lose out", "not have an advantage that others have – never learning an instrument", "chịu thiệt, không có lợi thế như người khác – không học nhạc cụ"),
   ("stressed-out (adj.)", "very worried and anxious", "căng thẳng, lo âu"),
   ("burnout (n.)", "illness or exhaustion from working too hard", "kiệt sức vì làm việc quá sức"),
 ])
)
